<script>
(()=>{const form=document.querySelector('[data-rn-form]');if(!form)return;const part=n=>form.querySelector(`[data-rn-part="${n}"]`),clean=v=>v.toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,6),yr=()=>document.querySelector('[data-rn-year-digits]').value==='2'?'{{ now('Africa/Lagos')->format('y') }}':'{{ now('Africa/Lagos')->format('Y') }}',next=()=>String(Math.max(1,Number(document.querySelector('[data-rn-next]').value||1))).padStart(Number(document.querySelector('[data-rn-length]').value),'0'),sep=()=>document.querySelector('[data-rn-separator]').value,code=i=>clean(i?.value||'')||'?',samples=[...form.querySelectorAll('[data-rn-level-row]')].slice(0,2);
function pieces(row,digits=next()){const v=[];if(part('school').checked)v.push(code(document.querySelector('[data-rn-school-code]')));if(part('section').checked)v.push(code(row?.querySelector?document.getElementById(row.querySelector('[data-rn-code]')?.dataset.rnSectionCodeSource||''):null));if(part('level').checked)v.push(code(row?.querySelector('[data-rn-code]')));if(part('year').checked)v.push(yr());v.push(digits);return v.join(sep())}
function states(kind){const inputs=[...form.querySelectorAll(`[data-rn-code-kind="${kind}"]`)],groups={};inputs.forEach(i=>{const g=kind==='level'&&part('section').checked?i.dataset.rnCodeGroup:'school',v=clean(i.value);groups[g]??={};if(v)groups[g][v]=(groups[g][v]||0)+1});return{inputs,groups}}
function render(){const so=part('school').checked,se=part('section').checked,le=part('level').checked,ye=part('year').checked;document.querySelector('[data-rn-school-field]').hidden=!so;document.querySelector('[data-rn-year-field]').hidden=!ye;document.querySelector('[data-rn-codes-card]').hidden=!se&&!le;form.querySelectorAll('[data-rn-section-row]').forEach(r=>r.hidden=!se);form.querySelectorAll('[data-rn-level-row]').forEach(r=>r.hidden=!le);document.querySelector('[data-rn-only-number]').hidden=so||se||le||ye;document.querySelector('[data-rn-movement-note]').hidden=se||le;
const a=samples[0],b=samples[1]||a;a&&document.querySelector('[data-rn-sample-one-label]').replaceChildren(a.querySelector('[data-rn-code]').dataset.rnLevelName);b&&document.querySelector('[data-rn-sample-two-label]').replaceChildren(b.querySelector('[data-rn-code]').dataset.rnLevelName);const an=pieces(a),bn=pieces(b);document.querySelector('[data-rn-sample-one]').textContent=an;document.querySelector('[data-rn-sample-two]').textContent=bn;const secInput=a?document.getElementById(a.querySelector('[data-rn-code]').dataset.rnSectionCodeSource||''):null;document.querySelector('[data-rn-strip]').innerHTML=[['School',code(document.querySelector('[data-rn-school-code]')),so],['Section',code(secInput),se],['Level',code(a?.querySelector('[data-rn-code]')),le],['Year',yr(),ye],['Number',next(),true]].map(x=>`<span class="rn-chip${x[2]?'':' off'}"><small>${x[0]}</small><b>${x[1]}</b></span>`).join('');
document.querySelector('[data-rn-saved-example]')?.replaceChildren(an);
const errors=[];if(so&&!/^[A-Z0-9]{2,6}$/.test(clean(document.querySelector('[data-rn-school-code]').value)))errors.push('School code needs 2 to 6 letters or numbers.');['section','level'].forEach(kind=>{const enabled=kind==='section'?se:le,{inputs,groups}=states(kind);inputs.forEach(i=>{const state=i.parentElement.querySelector('[data-rn-code-state]'),v=clean(i.value),g=kind==='level'&&se?i.dataset.rnCodeGroup:'school';let text='OK';if(enabled&&!v){text='Missing';errors.push(`${i.closest('.rn-code-row').querySelector('label').textContent.trim()} needs a code.`)}else if(enabled&&groups[g]?.[v]>1){text='Used twice';errors.push(`${kind==='section'?'Section':'Level'} code ${v} is used twice.`)}state.textContent=text;state.classList.toggle('bad',text!=='OK');i.setAttribute('aria-invalid',text!=='OK'?'true':'false')})});const summary=document.querySelector('[data-rn-code-summary]');summary.hidden=!errors.length;summary.textContent=[...new Set(errors)].join(' ');document.querySelector('[data-rn-save]').disabled=!!errors.length;
const fresh=String(1).padStart(Number(document.querySelector('[data-rn-length]').value),'0');document.querySelector('[data-rn-policy-example="keep_digits_change_prefix"]').textContent=`Example: ${an} → ${bn}`;document.querySelector('[data-rn-policy-example="new_prefix_sequence"]').textContent=`Example: ${an} → ${pieces(b,fresh)}`;document.querySelector('[data-rn-policy-example="keep_whole_number"]').textContent=`Example: ${an} → ${an}`}
form.querySelectorAll('input,select').forEach(c=>c.addEventListener('input',e=>{if(e.target.matches('[data-rn-code],[data-rn-school-code]'))e.target.value=clean(e.target.value);render()}));render()})();
</script></body></html>
